using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.World;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalBranchTests
{
    static WorldSession New(bool closed=true)=>new(RegionalBranch.Create(closed));
    static void Send(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.Submit(RegionalBranch.Order(s.DiagnosticSnapshot(),"request:move"),s.Revision).Code);
    static readonly string[] detour=["road","kasadera-access","kasadera-tange","tange-fort"];
    [Fact] public void FiveSourceLinkedAnchorsAndIndependentVersion(){var w=RegionalBranch.Create();Assert.Equal(5,w.Definitions.Sites.Length);Assert.Equal(5,RegionalBranch.Edges.Length);Assert.Contains("CC BY 4.0",RegionalBranch.Catalog.Credit);Assert.NotEqual(RegionalRoute.Version,w.Definitions.Version);Assert.Equal(2,w.Schema);foreach(var n in RegionalBranch.Catalog.Nodes){var p=JapanGeography.Project(new(n.Stop.LatitudeE7,n.Stop.LongitudeE7));Assert.Equal(new RoutePoint(p.EastMm,p.NorthMm),RegionalBranch.Nodes.Single(x=>x.Id==n.Id).Position);}}
    [Fact] public void PlansUseKnownEdgesAndSeparateTravelLengths(){var w=RegionalBranch.Create();Assert.Equal(new[]{"road","pass"},BranchRoutes.Plan("castle","village",[],w:w));Assert.Equal(detour,BranchRoutes.Plan("castle","village",["pass"],w:w));Assert.Equal(18339,BranchRoutes.Duration(["road","pass"],w:w));Assert.Equal(18342,BranchRoutes.Duration(detour,w:w));Assert.Equal(9172,BranchRoutes.Duration(BranchRoutes.Plan("village","castle",["pass"],true,w),true,w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(1001)][InlineData(11655)]
    public void HiddenTruthCannotChangeAnyObserverReadModelBeforeContact(int second){var a=New();var b=New(false);Send(a);Send(b);a.AdvanceTo(second);b.AdvanceTo(second);foreach(var actor in new[]{ContractFixture.Officer,ContractFixture.Lord,ContractFixture.Clerk})Assert.Equal(ContractJson.Write(a.GetBranchView(actor)),ContractJson.Write(b.GetBranchView(actor)));}
    [Fact] public void ObservationReroutesAtAtsutaWithoutTeleporting(){var s=New();Send(s);s.AdvanceTo(11655);Assert.Empty(s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);s.AdvanceTo(11656);var v=s.GetBranchView(ContractFixture.Officer);Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="fork").Position,v.Position);Assert.Equal(detour,v.PlannedEdges);Assert.Equal(new[]{"pass"},v.KnownBlockedEdges);Assert.Equal(18343,v.ArrivalAt);}
    [Fact] public void IssuerGetsClosureOnlyThroughDelayedEvidence(){var s=New();Send(s);s.AdvanceTo(17483);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);s.AdvanceTo(17484);Assert.Equal(new[]{"pass"},s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);var e=s.GetActorView(ContractFixture.Lord).Evidence.Single(e=>e.Claim=="route-block:pass");Assert.Equal(11656,e.ObservedAt);Assert.Equal(17484,e.RecordedAt);}
    [Fact] public void ArrivalAndKnownCompletionAreSeparate(){var s=New();Send(s);s.AdvanceTo(18343);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Equal(ContractFixture.Village,s.GetActorView(ContractFixture.Officer).Location.Site);s.AdvanceTo(27514);Assert.Contains(s.GetActorView(ContractFixture.Lord).Tasks,t=>t.KnownStatus.Contains("結果未確認"));s.AdvanceTo(27515);Assert.Equal("任務完了",s.GetActorView(ContractFixture.Lord).Tasks.Single().KnownStatus);}
    [Fact] public void UnblockedPassDoesNotDetour(){var s=New(false);Send(s);s.AdvanceTo(18340);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Empty(s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);Assert.Equal(new[]{"road","pass"},s.GetBranchView(ContractFixture.Officer).PlannedEdges);}
    [Theory][InlineData(1001)][InlineData(14656)] public void SaveRestorationKeepsDiscoveryPathAndEffects(long at){var s=New();Send(s);s.AdvanceTo(at);var root=Path.Combine(Path.GetTempPath(),"hakutai-regional-branch-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RegionalBranch.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,60));var load=store.Prepare("test");var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(load,host.Current,host.Current.Revision));Assert.True(host.Current.Paused);Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));
        host.Current.SetPaused(false);s.AdvanceTo(27515);host.Current.AdvanceTo(27515);var a=s.DiagnosticSnapshot();var b=host.Current.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.Branches),ContractJson.Write(b.Branches));Assert.Equal(a.EffectLedger,b.EffectLedger);Assert.Equal(a.Messaging.Messages,b.Messaging.Messages);Assert.Equal(a.Locations.Select(l=>l with{Revision=0}),b.Locations.Select(l=>l with{Revision=0}));}
    [Fact] public void WrongCatalogOrCorridorSchemaCannotLoad(){var s=New();Send(s);s.AdvanceTo(1001);var root=Path.Combine(Path.GetTempPath(),"hakutai-branch-deps-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,RegionalBranch.Create().Definitions).Save(s,"test",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,RegionalRoute.Create().Definitions).Prepare("test"));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,RegionalBranch.Create().Definitions with{Version="changed"}).Prepare("test"));}
    [Fact] public void ChangedCoordinateCannotKeepVersion(){var w=RegionalBranch.Create();w.Definitions=w.Definitions with{Sites=w.Definitions.Sites.Select((x,i)=>i==0?x with{LongitudeE7=x.LongitudeE7+1}:x).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void ForgedTimingAndDeliveryDoNotCreateTasks(){var s=New();var i=RegionalBranch.Order(s.DiagnosticSnapshot(),"request:move");Assert.Equal(ResultCode.InvalidInput,s.Submit(i with{WorkSeconds=1},s.Revision).Code);Assert.Equal(ResultCode.InvalidInput,s.Submit(i with{DeliverySeconds=0},s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Tasks);}
    [Fact] public void UnknownClosuresCanLeadToSafeStop(){var w=RegionalBranch.Create();w.Branches=w.Branches! with{BlockedEdges=["pass","kasadera-access"]};var s=new WorldSession(w);Send(s);s.AdvanceTo(20000);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="fork").Position,s.GetBranchView(ContractFixture.Officer).Position);}
    [Fact] public void ViewReadsHaveNoClockRandomOrMutationEffects(){var s=New();Send(s);s.AdvanceTo(14656);var before=ContractJson.Write(s.DiagnosticSnapshot());for(int i=0;i<20;i++){s.GetBranchView(ContractFixture.Officer);s.GetBranchView(ContractFixture.Lord);}Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact] public void LegacyMovementControlTerrainRevisionStaysUnchanged(){var s=new WorldSession(MovementControl.Create());s.Submit(BranchRoutes.Order(s.DiagnosticSnapshot(),"request:move"),s.Revision);s.AdvanceTo(5);Assert.Equal(BranchRoutes.Version,s.GetActorView(ContractFixture.Officer).Location.TerrainRevision);}
    [Fact] public void ReplayAfterDetourDoesNotExecuteTwice(){var s=New();var i=RegionalBranch.Order(s.DiagnosticSnapshot(),"request:move");s.Submit(i,s.Revision);s.AdvanceTo(27515);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));}
}
